<div class="page-shell"><article class="page-hero wrap"><span class="eyebrow"><?=e($issue['category'])?> · <?=e($issue['locality'])?></span><h1><?=e($issue['title'])?></h1><p><?=nl2br(e($issue['description']))?></p><div class="hero-buttons"><span class="status"><?=e(str_replace('_',' ',$issue['progress_status']))?></span><span><?=e($issue['supports'])?> supporters</span><?php if(auth()):?><form method="post" action="<?=url('issues/'.$issue['id'].'/support')?>"><?=csrf_field()?><button class="pill pill-dark">Support this issue</button></form><?php endif;?></div></article><section class="wrap two-column"><div><h2>Status timeline</h2><?php foreach($history as $h):?><article class="timeline-item"><strong><?=e(str_replace('_',' ',$h['new_status']))?></strong><p><?=e($h['public_update'])?></p><small><?=e(date('j M Y, g:i a',strtotime($h['created_at'])))?></small></article><?php endforeach;?></div><div><h2>Community comments</h2><?php foreach($comments as $c):?><article class="comment"><strong><?=e($c['full_name'])?></strong><p><?=e($c['body'])?></p></article><?php endforeach;?><p>Comments are moderated to protect privacy and constructive discussion.</p></div></section></div>
